problems.solution:
import math

def gaussian_pdf(x, mu, sigma):
    coef = 1 / (sigma * math.sqrt(2 * math.pi))
    expo = -(x - mu) ** 2 / (2 * sigma ** 2)
    return coef * math.exp(expo)

def dice_sum_dist(n):
    d = [1.0]
    for _ in range(n):
        new = [0.0] * (len(d) + 6)
        for s, p in enumerate(d):
            for f in range(1, 7):
                new[s + f] += p / 6
        d = new
    return d

import numpy as np

def fraction_within(x, k):
    m = x.mean()
    s = x.std()
    return (np.abs(x - m) <= k * s).mean()
